CREATE TABLE IF NOT EXISTS local_provider_session_drafts (handle TEXT PRIMARY KEY REFERENCES local_provider_sessions(handle) ON DELETE CASCADE, project_id TEXT NOT NULL REFERENCES projects(id), summary TEXT NOT NULL CHECK(length(summary) BETWEEN 1 AND 4096), updated_at INTEGER NOT NULL CHECK(updated_at > 0)); CREATE INDEX IF NOT EXISTS local_provider_session_drafts_project_updated_idx ON local_provider_session_drafts(project_id,updated_at DESC,handle);
